// Some portions generated by Co-Pilot
import { fireEvent, render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import VersionSelector from "../index";

const props = {
  activeVersionTab: 21,
  setActiveVersionTab: vi.fn(),
  versions: [
    { name: "25 - LTS", value: 25 },
    { name: "21 - LTS", value: 21 },
    { name: "17 - LTS", value: 17 },
  ],
};

describe("Version selection", () => {
  beforeEach(() => vi.clearAllMocks());

  it("renders correctly", () => {
    const { container } = render(<VersionSelector {...props} />);
    expect(container).toMatchSnapshot();
  });

  it("indicates the selected version semantically", () => {
    render(<VersionSelector {...props} />);
    expect(
      screen.getByRole("button", { name: "JDK 21 - LTS" }),
    ).toHaveAttribute("aria-pressed", "true");
    expect(
      screen.getByRole("button", { name: "JDK 25 - LTS" }),
    ).toHaveAttribute("aria-pressed", "false");
  });

  it("notifies the parent of an LTS choice exactly once", () => {
    render(<VersionSelector {...props} />);
    fireEvent.click(screen.getByRole("button", { name: "JDK 17 - LTS" }));
    expect(props.setActiveVersionTab).toHaveBeenCalledExactlyOnceWith(17);
  });

  it("notifies the parent when All Versions is selected", () => {
    render(<VersionSelector {...props} />);
    fireEvent.click(screen.getAllByTestId("version-tab")[0]);
    expect(props.setActiveVersionTab).toHaveBeenCalledExactlyOnceWith(1);
  });

  it("has no accessibility violations", async () => {
    const { container } = render(<VersionSelector {...props} />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
